package cfg

import (
	"encoding/json"
	"os"
)

// Config is the application configuration.
type Config struct {
	Name string `json:"name"`
	Port int    `json:"port"`
}

// LoadConfig reads a JSON config file.
func LoadConfig(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var c Config
	if err := json.Unmarshal(data, &c); err != nil {
		return nil, err
	}
	return &c, nil
}

