package cfg

import (
	"os"
	"path/filepath"
	"testing"
)

func TestLoadConfig(t *testing.T) {
	p := filepath.Join(t.TempDir(), "c.json")
	os.WriteFile(p, []byte(`{"name":"x","port":8}`), 0o644)
	c, err := LoadConfig(p)
	if err != nil || c.Name != "x" || c.Port != 8 {
		t.Fatalf("LoadConfig = %+v, %v", c, err)
	}
}

