package main

import (
	"fmt"
	"os"

	"example.com/cfg"
)

func main() {
	c, err := cfg.LoadConfig(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, "loadconfig:", err)
		os.Exit(1)
	}
	fmt.Println(c.Name, c.Port)
}

